package main

import (
	"fmt"
	"strconv"
)

func grade(score int) string {
	if score >= 90 {
		return "A"
	} else if score >= 80 {
		return "B"
	} else if score >= 70 {
		return "C"
	} else if score >= 60 {
		return "D"
	}
	return "F"
}

func main() {
	// Dasar if-else
	scores := []int{95, 82, 71, 65, 45}
	for _, s := range scores {
		fmt.Printf("Score %d -> Grade %s\n", s, grade(s))
	}

	// Short init statement
	if n, err := strconv.Atoi("42"); err == nil {
		fmt.Printf("Berhasil parse: %d (double: %d)\n", n, n*2)
	} else {
		fmt.Println("Parse error:", err)
	}

	// Coba parse string yang invalid
	if _, err := strconv.Atoi("abc"); err != nil {
		fmt.Println("Expected error:", err)
	}
}
